mapper.select:
SELECT b.* FROM `att_clock_in_records` a
inner join `att_classes_record` b on a.`classes_id`=b.`classes_id` and a.`classes_version`=b.`version`
where a.`id`=#{clockInId}

select * from `att_clock_in_records`
where `user_id`=#{userId}
  and `clock_in_date`=#{clockInDate}
  and `state` in ('EARLY_CHECKED','LATE_CHECKED','LACK_CHECKED')
  and `clock_type` in ('START','END')
limit 1

select * from att_clock_in_records
where `user_id`=#{userId}
  and `clock_in_date`=#{clockInDate}
  and `state` = 'NORMAL'
  and `clock_type` in ('START','END')
    limit 1
